INSERT INTO platform_private.learning_modules (id, module_key, version, track, metadata)
VALUES
  ('afbc61ca-e798-54ac-8239-1569327cebf1', 'csca-math', '1.1.0', 'csca-math', '{"title_ru":"Математика","title_ky":"Математика","level_note_ru":"Задания на английском, как на экзамене. Объяснения на русском и кыргызском, термины на английском. Все задания решаются без калькулятора.","level_note_ky":"Тапшырмалар экзамендегидей англис тилинде. Түшүндүрмөлөр орус жана кыргыз тилдеринде, терминдер англис тилинде. Бардык тапшырмалар калькуляторсуз чыгарылат.","syllabus_edition":"2025","syllabus_url":"https://csca.cn/about/testprep","sections":[{"section":1,"title_ru":"Множества и неравенства","title_ky":"Көптүктөр жана барабарсыздыктар","title_en":"Sets and Inequalities","mock_items_estimate":7,"points":[{"point":"1.1","label_ru":"Множества: определение, операции, способы записи","label_ky":"Көптүктөр: аныктамасы, амалдар, жазуу жолдору","label_en":"Sets"},{"point":"1.2","label_ru":"Неравенства: свойства и способы решения, включая квадратные и дробно-рациональные","label_ky":"Барабарсыздыктар: касиеттери жана чыгаруу жолдору, анын ичинде квадраттык жана бөлчөк-рационалдык","label_en":"Inequalities"}]},{"section":2,"title_ru":"Функции","title_ky":"Функциялар","title_en":"Functions","mock_items_estimate":19,"points":[{"point":"2.1","label_ru":"Функция и её свойства: область определения, множество значений, монотонность, чётность","label_ky":"Функция жана анын касиеттери: аныкталуу областы, маанилер областы, монотондуулук, жуптук","label_en":"Function concepts and properties"},{"point":"2.2","label_ru":"Основные элементарные функции: степенная, показательная, логарифмическая, тригонометрические","label_ky":"Негизги элементардык функциялар: даражалуу, көрсөткүчтүү, логарифмдик, тригонометриялык","label_en":"Basic elementary functions"},{"point":"2.3","label_ru":"Последовательности: общий член и сумма арифметической и геометрической прогрессий","label_ky":"Удаалаштыктар: арифметикалык жана геометриялык прогрессиялардын жалпы мүчөсү жана суммасы","label_en":"Sequences"},{"point":"2.4","label_ru":"Основы производной: определение, геометрический смысл, простые применения","label_ky":"Туундунун негиздери: аныктамасы, геометриялык мааниси, жөнөкөй колдонуулар","label_en":"Derivatives"}]},{"section":3,"title_ru":"Геометрия и алгебра","title_ky":"Геометрия жана алгебра","title_en":"Geometry and Algebra","mock_items_estimate":14,"points":[{"point":"3.1","label_ru":"Аналитическая геометрия на плоскости: прямая, окружность, эллипс, гипербола, парабола","label_ky":"Тегиздиктеги аналитикалык геометрия: түз сызык, айлана, эллипс, гипербола, парабола","label_en":"Plane analytic geometry"},{"point":"3.2","label_ru":"Векторы и комплексные числа: действия","label_ky":"Векторлор жана комплекстүү сандар: амалдар","label_en":"Vectors and complex numbers"},{"point":"3.3","label_ru":"Стереометрия: прямоугольная система координат в пространстве, простые тела","label_ky":"Стереометрия: мейкиндиктеги тик бурчтуу координаталар системасы, жөнөкөй телолор","label_en":"Solid geometry"}]},{"section":4,"title_ru":"Вероятность и статистика","title_ky":"Ыктымалдык жана статистика","title_en":"Probability and Statistics","mock_items_estimate":8,"points":[{"point":"4.1","label_ru":"Классическая вероятность и вычисление вероятностей","label_ky":"Классикалык ыктымалдык жана ыктымалдыктарды эсептөө","label_en":"Classical probability"},{"point":"4.2","label_ru":"Числовые характеристики данных: среднее, дисперсия","label_ky":"Маалыматтардын сандык мүнөздөмөлөрү: орточо маани, дисперсия","label_en":"Numerical characteristics of data"},{"point":"4.3","label_ru":"Нормальное распределение: основные понятия","label_ky":"Нормалдуу бөлүштүрүү: негизги түшүнүктөр","label_en":"Normal distribution"}]}]}'::JSONB);
