  ('03bd2de3-87fc-543c-89fb-16e5e73578a5', 'afbc61ca-e798-54ac-8239-1569327cebf1', 'item-parabola-triangle', '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 330" width="400" height="330" font-family="Golos Text, -apple-system, Segoe UI, Roboto, Arial, sans-serif"><title>Parabola y^2 = 4x with focus F, directrix l, a point P and the foot D of the perpendicular from P to l</title><rect width="400" height="330" rx="12" fill="#ffffff"/><line x1="78" y1="323.6" x2="78" y2="10" stroke="#191714" stroke-width="1.8" stroke-dasharray="7 5" stroke-linecap="round"/><line x1="33.2" y1="170" x2="370.8" y2="170" stroke="#191714" stroke-width="1.5" stroke-linecap="round"/><polygon points="378.8,170 369.8,174.5 369.8,165.5" fill="#191714"/><line x1="110" y1="326.8" x2="110" y2="14.8" stroke="#191714" stroke-width="1.5" stroke-linecap="round"/><polygon points="110,6.8 114.5,15.8 105.5,15.8" fill="#191714"/><text x="374.8" y="194" font-size="15" fill="#191714" text-anchor="middle"><tspan font-style="italic">x</tspan></text><text x="98" y="16.8" font-size="15" fill="#191714" text-anchor="middle"><tspan font-style="italic">y</tspan></text><path d="M272,314 L266.5,311.5 L261.1,309.1 L255.9,306.6 L250.7,304.2 L245.6,301.7 L240.6,299.3 L235.7,296.8 L230.8,294.4 L226.1,291.9 L221.5,289.5 L217,287 L212.5,284.6 L208.2,282.1 L203.9,279.7 L199.8,277.2 L195.7,274.7 L191.7,272.3 L187.9,269.8 L184.1,267.4 L180.4,264.9 L176.8,262.5 L173.3,260 L169.9,257.6 L166.6,255.1 L163.4,252.7 L160.3,250.2 L157.2,247.8 L154.3,245.3 L151.5,242.9 L148.7,240.4 L146.1,237.9 L143.5,235.5 L141,233 L138.7,230.6 L136.4,228.1 L134.2,225.7 L132.1,223.2 L130.1,220.8 L128.2,218.3 L126.4,215.9 L124.7,213.4 L123.1,211 L121.6,208.5 L120.2,206.1 L118.8,203.6 L117.6,201.1 L116.4,198.7 L115.4,196.2 L114.4,193.8 L113.6,191.3 L112.8,188.9 L112.1,186.4 L111.5,184 L111,181.5 L110.6,179.1 L110.3,176.6 L110.1,174.2 L110,171.7 L110,169.3 L110.1,166.8 L110.2,164.3 L110.5,161.9 L110.9,159.4 L111.3,157 L111.9,154.5 L112.5,152.1 